    for i in range(2, target // 2 + 1, 2):
        for j in range(i, (target - i) // 2 + 1, 2):
            for k in range(j, (target - i - j) // 2 + 1, 2):
                for last in range(k, (target - i - j - k) // 2 + 1, 2):
                    if i + j + k + last == target:
                        return True
    return False

